typedef struct { double total; } Sum;
static void add_line(gpointer value, gpointer ctx) {   /* the "message" */
    Sum *sum = ctx;                                     /* untyped context */
    sum->total += order_line_total(value);
}
double orders_total(GList *orders) {
    Sum sum = { 0 };
    g_list_foreach(orders, add_line, &sum);
    return sum.total;
}
